"use client";
import { useState } from "react";
import { Plus, Minus } from "lucide-react";
import Reveal from "./Reveal";
import type { Project } from "@/lib/resume-data";

export default function ProjectCard({ project, defaultOpen = false }: { project: Project; defaultOpen?: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  const panelId = `project-${project.id}`;

  return (
    <Reveal tag="article" className="h-full">
      <div className="flex h-full flex-col rounded-xl border border-ink/10 bg-card p-6 md:p-7">
        <div className="flex items-center justify-between gap-3">
          <p className="font-mono text-[12px] font-medium uppercase tracking-[0.14em] text-accent">
            {project.status}
          </p>
        </div>
        <h3 className="mt-2 font-display text-[26px] font-medium leading-tight tracking-tight text-ink">
          {project.title}
        </h3>
        <p className="mt-1 text-sm text-muted">{project.subtitle}</p>

        <div className="mt-4 flex flex-wrap gap-1.5">
          {project.tools.map((t) => (
            <span
              key={t}
              className="rounded-md bg-ink/[0.05] px-2.5 py-1 text-[12.5px] font-medium text-ink-soft"
            >
              {t}
            </span>
          ))}
        </div>

        <dl className="mt-5 grid grid-cols-2 gap-px overflow-hidden rounded-lg border border-ink/10 bg-ink/10">
          {project.specs.map((s) => (
            <div key={s.label} className="bg-card px-4 py-3">
              <dt className="text-[11px] font-semibold uppercase tracking-[0.12em] text-muted">
                {s.label}
              </dt>
              <dd className="mt-0.5 text-[13.5px] font-medium leading-snug text-ink">
                {s.value}
              </dd>
            </div>
          ))}
        </dl>

        <div className="flex-1 pt-4">
          <p className="text-[13px] text-muted">
            Role — <span className="font-medium text-ink">{project.role}</span>
          </p>
          <div
            id={panelId}
            className={`grid transition-all duration-300 ease-out ${
              open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
            }`}
          >
            <div className="overflow-hidden">
              <div className={`space-y-3 text-[14.5px] leading-relaxed text-ink-soft ${open ? "pt-3" : ""}`}>
                <p>
                  <strong className="font-semibold text-ink">Problem. </strong>
                  {project.problem}
                </p>
                <p>
                  <strong className="font-semibold text-ink">Solution. </strong>
                  {project.solution}
                </p>
                <p>
                  <strong className="font-semibold text-ink">Result. </strong>
                  {project.result}
                </p>
              </div>
            </div>
          </div>
          {!open && (
            <p className="mt-2 text-[14.5px] leading-relaxed text-ink-soft line-clamp-2">
              {project.problem}
            </p>
          )}
        </div>

        <button
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          aria-controls={panelId}
          className="mt-5 flex w-full items-center justify-between border-t border-ink/10 pt-4 text-[13.5px] font-semibold text-ink transition-colors hover:text-accent focus-visible:outline-2 focus-visible:outline-accent"
        >
          <span>{open ? "Hide details" : "Show details"}</span>
          {open ? (
            <Minus className="h-4 w-4" aria-hidden />
          ) : (
            <Plus className="h-4 w-4" aria-hidden />
          )}
        </button>
      </div>
    </Reveal>
  );
}
